{'datasets': ['sagard21/autotrain-data-code-explainer'], 'language': ['en'], 'license': 'mit', 'pipeline_tag': 'summarization', 'tags': ['autotrain', 'summarization'], 'widget': [{'text': 'class Solution(object):
  def isValid(self, s):
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}
    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)
    return not stack
'}], 'co2_eq_emissions': {'emissions': 5.393079045128973}}

